Ext._define('rh.teletrabalho.mark_telework.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'rh.teletrabalho.mark_telework.Window',

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Cod', dataIndex: 'pk', width: 50, hidden: true},
                    {header: 'Descricao', dataIndex: 'unicode', id: 'autoExpandColumn', hidden: true},
                    {header: 'Descrição da Meta', dataIndex: 'description_mark', width: 250, hidden: true},
                    {header: 'Situação da Meta', dataIndex: 'mark_situation_display', width: 150, hidden: true},
                    {header: 'Competência', dataIndex: 'competence', width: 90, renderer: Ext.util.Format.dateRenderer('m/Y')},
                    {header: 'Código VDF', dataIndex: 'request', width: 100},
                    {header: 'Situação', dataIndex: 'status', width: 100},
                    {header: 'Observação do Solicitante', dataIndex: 'observacao_solicitante', width: 150},
                    {header: 'Observação do Aprovador', dataIndex: 'aproove_observation', width: 150},
                    {header: 'Gerou Saldo Devedor?', dataIndex: 'possui_saldo_devedor', width: 70, renderer: toolkit.util.formatIconYesNo},
                    {header: 'Possui Anexo?', dataIndex: 'possui_anexo', width: 70, renderer: toolkit.util.formatIconYesNo},
                    {header: 'Possui Afastamento?', dataIndex: 'possui_afastamento', width: 70, renderer: toolkit.util.formatIconYesNo},
                ]
            );

        return this._columnModel;
    },

    reqDownload: function(controllerNome, metodoNome, params, arquivoNome){
        Ext.Ajax.request({
            url: toolkit.util.Normalize.controller_action(controllerNome, metodoNome),
            params: params,
            success: function(request) {
                var obj = Ext.decode(request.responseText);
                if(obj.success == true){
                    this.downloadPdfFromBase64(obj.arquivo, arquivoNome);
                    Ext.Msg.show({
                        title: this.title,
                        icon: Ext.Msg.INFO,
                        buttons: Ext.Msg.OK,
                        msg: 'Download solicitado com sucesso!'
                    });
                }else{
                    Ext.Msg.show({
                        title: this.title,
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: obj.message
                    });
                }
            },
            failure: function() {
                Ext.Msg.show({
                    title: this.title,
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Download indisponivel no momento, tente novamente mais tarde.'
                });
            },
            scope: this
        });
    },

    getConfigCustomActions: function(){
        return [
            {
                iconCls: 'icon-16px icon-fopag icon-compile',
                tooltip: 'Download anexo',
                scope: this,
                handler: function(action, index) {
                    var dados = action._store.getAt(index).data
                    params = { 'request_pk': dados.request };

                    this.reqDownload('RHGestorMarkTelework', 'download_anexo', params, 'documento.pdf');
                }
            },
        ];
    },
});

core.RestfulGrid.register(
    'rh.teletrabalho.mark_telework.Restful',
    'rh.teletrabalho.mark_telework.Grid'
);

